export type HumanState={readonly enrollmentFactors:readonly {id:string;type:string}[];readonly enrollmentBusy:boolean;readonly mfaFactors:readonly {id:string;type:string}[];readonly mfaBusy:boolean;readonly phase:HumanPhase;readonly generation:number;readonly workspace:string|null;readonly expiresAt:number|null;readonly workspaceOptions:readonly {id:string;name:string}[]};
