export interface HumanSession {beginMfaEnrollment():Promise<MfaEnrollment>;confirmMfaEnrollment(factorId:string,code:string):Promise<{confirmed:true;logout:'confirmed'|'unconfirmed'|'not_requested'}>;verifyMfa(factorId:string,code:string):Promise<void>;reauthenticate():Promise<void>;changePassword(currentPassword:string,password:string,nonce?:string):Promise<{changed:true;logout:'confirmed'|'unconfirmed'|'not_requested'}>;state():HumanState;signIn(fields:{email:string;password:string;workspace:string}):Promise<void>;selectWorkspace(id:string):void;authorization():Promise<Authorization>;resume():Promise<Authorization>;signOut(options?:{scope:'local'|'global'}):Promise<'confirmed'|'unconfirmed'|'not_requested'>;reject(p:Authorization):boolean;current(p:Authorization):boolean;canDispatch(p:Authorization):boolean;sameCredential(p:Authorization):boolean;}
